// Theirs -> ours half of the cross-tool recovery suite (scripts/interop/): shares
// generated by other SLIP-39 tools, recorded in tests/interop/*.json by
// scripts/interop/run.py, must recover here: with no external tool needed.
// The ours -> theirs half needs the tools themselves and runs in that script.
// For tools that work with BIP39 phrases, the recovered secret must also be
// the original phrase, word for word, through pkc-core's Phrase.

use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    tool: String,
    version: String,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    secret_hex: String,
    bip39_phrase: Option<String>,
    passphrase: String,
    wrong_passphrase: String,
    wrong_secret_hex: String,
    extendable: bool,
    iteration_exponent: u8,
    mnemonics: Vec<Vec<String>>,
    recovery_sets: Vec<Vec<String>>,
    surplus_set: Option<Vec<String>>,
    tampered_set: Vec<String>,
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn refs(set: &[String]) -> Vec<&str> {
    set.iter().map(String::as_str).collect()
}

fn check(fixture: &Fixture, failures: &mut Vec<String>) {
    let tool = format!("{} {}", fixture.tool, fixture.version);
    for case in &fixture.cases {
        let name = format!("{tool}, {}", case.name);
        let combine = |set: &[String], passphrase: &str| pkc_slip39::combine(&refs(set), passphrase).map(|s| hex_encode(&s));

        for (i, set) in case.recovery_sets.iter().enumerate() {
            match combine(set, &case.passphrase) {
                Ok(hex) if hex == case.secret_hex => {}
                other => failures.push(format!("{name}: recovery set {i}: got {other:?}")),
            }
            if let Some(expected) = &case.bip39_phrase {
                let recovered = pkc_slip39::combine(&refs(set), &case.passphrase)
                    .map_err(|e| e.to_string())
                    .and_then(|s| pkc_core::Phrase::from_entropy(&s).map_err(|e| e.to_string()))
                    .map(|p| p.to_words().to_string());
                if recovered.as_ref() != Ok(expected) {
                    failures.push(format!("{name}: recovery set {i} as a phrase: got {recovered:?}"));
                }
            }
        }
        if let Some(phrase) = &case.bip39_phrase {
            match pkc_core::Phrase::parse(phrase) {
                Ok(p) if hex_encode(&p.entropy()) == case.secret_hex => {}
                _ => failures.push(format!("{name}: the tool's phrase doesn't parse to the case's secret")),
            }
        }

        // Surplus shares are ignored here, whatever the generating tool does
        // with them (recorded in the fixture as surplus_accepted_by_tool).
        if let Some(surplus) = &case.surplus_set {
            match combine(surplus, &case.passphrase) {
                Ok(hex) if hex == case.secret_hex => {}
                other => failures.push(format!("{name}: surplus set: got {other:?}")),
            }
        }

        // A wrong passphrase must give the same wrong bytes the tool itself gave.
        match combine(&case.recovery_sets[0], &case.wrong_passphrase) {
            Ok(hex) if hex == case.wrong_secret_hex => {}
            other => failures.push(format!("{name}: wrong passphrase: got {other:?}, the tool gave {}", case.wrong_secret_hex)),
        }

        if combine(&case.tampered_set, &case.passphrase).is_ok() {
            failures.push(format!("{name}: a tampered share was accepted"));
        }

        for mnemonic in case.mnemonics.iter().flatten() {
            match pkc_slip39::inspect(mnemonic) {
                Ok(info) if info.extendable == case.extendable && info.iteration_exponent == case.iteration_exponent => {}
                other => failures.push(format!("{name}: inspect: got {other:?}")),
            }
        }
    }
}

#[test]
fn shares_from_other_tools_recover() {
    let fixtures = [
        include_str!("interop/python-shamir-mnemonic.json"),
        include_str!("interop/python-slip39.json"),
        include_str!("interop/seedkit.json"),
    ];

    let mut failures = Vec::new();
    let mut cases = 0;
    for raw in fixtures {
        let fixture: Fixture = serde_json::from_str(raw).expect("fixture must parse");
        assert!(!fixture.cases.is_empty(), "{} fixture has no cases", fixture.tool);
        cases += fixture.cases.len();
        check(&fixture, &mut failures);
    }

    assert!(failures.is_empty(), "{} failure(s) across {cases} cases:\n{}", failures.len(), failures.join("\n"));
}
